if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_container_options_policy() {
    echo -e "auto\tRestrict when the container daemon socket is disabled"
    echo -e "restrict\tAlways restrict host paths and options"
    echo -e "allow\tPermit host paths and options"
}

_choice_defaultbranch() {
    git branch --format='%(refname:short)' 2>/dev/null
}

_choice_env() {
    env | _argc_util_transform format==
}

_choice_event() {
    _helper_act_query '(.on | select(tag == "!!str")), (.on | select(tag == "!!seq") | .[]), (.on | select(tag == "!!map") | keys | .[])'
}

_choice_input() {
    _helper_act_named "${argc_input_file:-.input}"
}

_choice_job() {
    _helper_act_query '.jobs | keys | .[]'
}

_choice_matrix() {
    _helper_act_query '.jobs[] | .strategy.matrix | select(tag == "!!map") | keys | .[] | select(. != "include" and . != "exclude")' \
        | _argc_util_transform suffix=: nospace
}

_choice_network() {
    command -v docker >/dev/null 2>&1 || return 0
    docker network ls --format '{{.Name}}' 2>/dev/null
}

_choice_platform() {
    _helper_act_query '.jobs[] | ."runs-on" | .. | select(tag == "!!str") | select(test("^\\$") | not)' \
        | _argc_util_transform suffix== nospace
}

_choice_remote_name() {
    git remote 2>/dev/null
}

_choice_replace_ghe_action() {
    _helper_act_query '.jobs[].steps[].uses | select(tag == "!!str") | select(test("^\\$") | not) | split("@")[0]'
}

_choice_secret() {
    _helper_act_named "${argc_secret_file:-.secrets}"
}

_choice_var() {
    _helper_act_named "${argc_var_file:-.vars}"
}

_helper_act_named() {
    local file="$1" found
    if [[ ! -f "$file" ]]; then
        found="$(_argc_util_path_search_parent "$file")"
        [[ -n "$found" ]] || return 0
        file="$found"
    fi
    gawk -F= '/^[A-Za-z_][A-Za-z0-9_]*=/ { print $1 }' "$file"
}

_helper_act_query() {
    local dir file
    command -v yq >/dev/null 2>&1 || return 0
    dir="$(_helper_act_workflow_dir)" || return 0
    [[ -n "$dir" ]] || return 0
    for file in "$dir"/*.yml "$dir"/*.yaml; do
        [[ -f "$file" ]] || continue
        yq -r "$1" "$file" 2>/dev/null
    done
}

_helper_act_workflow_dir() {
    local dir="${argc_workflows[0]:-.github/workflows}"
    if [[ -f "$dir" ]]; then
        dirname "$dir"
    elif [[ -d "$dir" ]]; then
        printf '%s\n' "$dir"
    fi
}
